tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_issue_planning_items",
    "description": "Listet Requirements, die durch Readiness fuer plan-only Issue Planning freigegeben sind.",
    "parameters": {
      "type": "object",
      "properties": {
        "limit": {
          "type": "integer",
          "default": 80
        }
      }
    }
  },
  {
    "type": "function",
    "name": "search_issue_planning_items",
    "description": "Sucht in freigegebenen Requirements nach Stichworten.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 30
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_issue_planning_item",
    "description": "Liest ein freigegebenes Requirement inklusive Text, Quellen und Provenienz.",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_seed_issue_plan",
    "description": "Liefert einen deterministischen Seed-Plan mit einem CREATE-Issue pro Requirement.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "check_issue_plan",
    "description": "Prueft IssuePlanItems deterministisch. Nutze dies vor dem Speichern.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "issuePlanId": {
                "type": "string"
              },
              "operation": {
                "type": "string"
              },
              "title": {
                "type": "string"
              },
              "description": {
                "type": "string"
              },
              "sourceRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "acceptanceCriteria": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "labels": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "dependencies": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "requiresHumanReview": {
                "type": "boolean"
              },
              "metadata": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                }
              }
            },
            "required": [
              "issuePlanId",
              "operation",
              "title",
              "description",
              "sourceRequirementIds",
              "acceptanceCriteria",
              "labels",
              "dependencies",
              "rationale",
              "requiresHumanReview",
              "metadata"
            ]
          }
        }
      },
      "required": [
        "items"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_issue_plan",
    "description": "Speichert deinen finalen IssuePlan. Rufe dies genau einmal am Ende auf.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "issuePlanId": {
                "type": "string"
              },
              "operation": {
                "type": "string"
              },
              "title": {
                "type": "string"
              },
              "description": {
                "type": "string"
              },
              "sourceRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "acceptanceCriteria": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "labels": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "dependencies": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "requiresHumanReview": {
                "type": "boolean"
              },
              "metadata": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                }
              }
            },
            "required": [
              "issuePlanId",
              "operation",
              "title",
              "description",
              "sourceRequirementIds",
              "acceptanceCriteria",
              "labels",
              "dependencies",
              "rationale",
              "requiresHumanReview",
              "metadata"
            ]
          }
        }
      },
      "required": [
        "items"
      ]
    }
  }
]

tags.gen_ai.input.messages:
[
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "Beginne jetzt mit plan-only Issue Planning.\n\nDu bekommst ausschliesslich Requirements, die durch RequirementsReadiness fuer Issue Planning\nfreigegeben wurden. Erkunde sie mit deinen Tools.\n\nErzeuge einen IssuePlan. Plane keine GitHub-Schreiboperation. Pruefe deinen Plan mit\ncheck_issue_plan und speichere genau einmal mit save_issue_plan."
      }
    ]
  }
]
